class Point {
    constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
    }

    static from(obj) {
        return new Point(obj.x, obj.y);
    }

    clone() {
        return new Point(this.x, this.y);
    }

    set(x, y) {
        this.x = x;
        this.y = y;
        return this;
    }

    add(other) {
        return new Point(this.x + other.x, this.y + other.y);
    }

    sub(other) {
        return new Point(this.x - other.x, this.y - other.y);
    }

    mul(k) {
        return new Point(this.x * k, this.y * k);
    }

    div(k) {
        return this.mul(1.0 / k);
    }

    rot90() {
        return new Point(-this.y, this.x);
    }

    dot(other) {
        return this.x * other.x + this.y * other.y;
    }

    cross(other) {
        return this.x * other.y - this.y * other.x;
    }

    mod2() {
        return this.dot(this);
    }

    mod() {
        return Math.sqrt(this.mod2());
    }

    unit() {
        const m = this.mod();
        return m < 1e-12 ? new Point(0, 0) : this.div(m);
    }

    rotate(alpha) {
        const sa = Math.sin(alpha);
        const ca = Math.cos(alpha);
        return new Point(this.x * ca - this.y * sa, this.x * sa + this.y * ca);
    }

    distanceTo(other) {
        return this.sub(other).mod();
    }
}

const EPS = 1e-9;
const PI = Math.acos(-1.0);

function ptoV(a, b) {
    return b.sub(a);
}

function corner2V(a, b) {
    const cosVal = a.dot(b) / a.mod() / b.mod();
    return Math.acos(Math.max(-1, Math.min(1, cosVal)));
}

function vRotate(v, alpha) {
    return v.rotate(alpha);
}

function pRotate(p, o, alpha) {
    return o.add(vRotate(ptoV(o, p), alpha));
}

function getVV(v) {
    return vRotate(v, PI / 2);
}

function shadowPOnLine(p, a, b) {
    const ab = ptoV(a, b);
    const ap = ptoV(a, p);
    const abUnit = ab.unit();
    const projLen = ab.dot(ap) / ab.mod();
    return a.add(abUnit.mul(projLen));
}

function lineCrossCircle(a, b, o, r) {
    const ret = [];
    const t = shadowPOnLine(o, a, b);
    const ot = ptoV(o, t);
    const dist = ot.mod();

    if (dist - r > EPS) return ret;

    if (Math.abs(dist - r) < EPS) {
        ret.push(t);
        return ret;
    }

    const lr = Math.sqrt(r * r - ot.mod2());
    const taDir = ptoV(t, a).unit();
    const tbDir = ptoV(t, b).unit();
    ret.push(t.add(taDir.mul(lr)));
    ret.push(t.add(tbDir.mul(lr)));
    return ret;
}

function pointTangentCircle(p, o, r) {
    const ret = [];
    const po = ptoV(o, p); // vector from o to p? Wait C++: Vec po = PtoV(p,o) -> o - p.
    // C++: double x2 = VecMod2(p-o); // (p-o) is vector from o to p.
    const op = p.sub(o); // vector from o to p
    const x2 = op.mod2();
    const d2 = x2 - r * r;

    if (d2 < -EPS) return ret;
    if (r <= EPS) {
        ret.push(o.clone());
        ret.push(o.clone());
        return ret;
    }

    const d2Safe = Math.max(d2, 0);
    // q1 = o + (p-o) * (r*r/x2)
    const q1 = o.add(op.mul(r * r / x2));
    // q2 = (p-o).rot90() * (-r*sqrt(d2) / x2)
    const q2 = op.rot90().mul(-r * Math.sqrt(d2Safe) / x2);

    ret.push(q1.sub(q2));
    ret.push(q1.add(q2));
    return ret;
}

function pOnSeg(p, a, b) {
    if (Math.abs(ptoV(a, b).cross(ptoV(a, p))) > EPS) return false;
    if (Math.min(a.x, b.x) > p.x + EPS || p.x > Math.max(a.x, b.x) + EPS) return false;
    if (Math.min(a.y, b.y) > p.y + EPS || p.y > Math.max(a.y, b.y) + EPS) return false;
    return true;
}

function pDisLine(p, a, b) {
    return shadowPOnLine(p, a, b).distanceTo(p);
}

// Global variables for check function
let g_p, g_s, g_vp, g_vs, g_r, g_sita;

function check(t) {
    const len_or = g_p.mod();
    const angle = g_sita + t * g_vp / len_or;
    const e = new Point(len_or * Math.cos(angle), len_or * Math.sin(angle));

    const ccp = lineCrossCircle(g_s, e, new Point(0, 0), g_r);

    // If no intersection or intersection not on segment
    if (ccp.length !== 2 || (!pOnSeg(ccp[0], g_s, e) && !pOnSeg(ccp[1], g_s, e))) {
        return g_vs * t >= e.distanceTo(g_s);
    }

    // Tangent points from s
    let ttp1 = pointTangentCircle(g_s, new Point(0, 0), g_r);
    if (pDisLine(ttp1[0], g_s, e) > pDisLine(ttp1[1], g_s, e)) {
        [ttp1[0], ttp1[1]] = [ttp1[1], ttp1[0]];
    }
    const l1 = g_s.distanceTo(ttp1[0]);

    // Tangent points from e
    let ttp2 = pointTangentCircle(e, new Point(0, 0), g_r);
    if (pDisLine(ttp2[0], g_s, e) > pDisLine(ttp2[1], g_s, e)) {
        [ttp2[0], ttp2[1]] = [ttp2[1], ttp2[0]];
    }
    const l2 = e.distanceTo(ttp2[0]);

    const alph = corner2V(ptoV(new Point(0, 0), ttp1[0]), ptoV(new Point(0, 0), ttp2[0]));

    return l1 + l2 + alph * g_r < g_vs * t;
}

function solve() {
    const readline = require('readline');
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });

    const lines = [];
    rl.on('line', (line) => {
        if (line.trim() === '') return;
        lines.push(line.trim());
    });

    rl.on('close', () => {
        const out = [];
        for (const line of lines) {
            const parts = line.split(/\s+/).map(Number);
            if (parts.length < 7) continue;

            g_p = new Point(parts[0], parts[1]);
            g_vp = parts[2];
            g_s = new Point(parts[3], parts[4]);
            g_vs = parts[5];
            g_r = parts[6];

            g_sita = Math.acos(g_p.x / g_p.mod());
            if (g_p.y < 0) g_sita = -g_sita;

            let left = 0;
            let right = 1e10;

            for (let i = 0; i < 100; i++) { // 100 iterations enough for 1e-12 precision on 1e10 range
                const mid = (left + right) * 0.5;
                if (check(mid)) {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            out.push(left.toFixed(9));
        }
        process.stdout.write(out.join('\n'));
    });
}

