function PtoV(a, b) {
    return new Point(b.x - a.x, b.y - a.y);
}

function dMult(a, b) {
    return a.x * b.x + a.y * b.y;
}

function xMult(a, b) {
    return a.x * b.y - a.y * b.x;
}

function VecMod(a) {
    return Math.sqrt(dMult(a, a));
}

function VecMod2(a) {
    return dMult(a, a);
}

function Corner2V(a, b) {
    const modA = VecMod(a);
    const modB = VecMod(b);
    if (modA < EPS || modB < EPS) return 0;
    const cosVal = dMult(a, b) / modA / modB;
    // Clamp to [-1, 1] to avoid NaN due to precision errors
    return Math.abs(Math.acos(Math.max(-1, Math.min(1, cosVal))));
}

function VecUnit(a) {
    const mod = VecMod(a);
    if (mod < EPS) return new Point(0, 0);
    return a.div(mod);
}

function VRotate(v, alph) {
    const sa = Math.sin(alph);
    const ca = Math.cos(alph);
    return new Point(v.x * ca - v.y * sa, v.x * sa + v.y * ca);
}

function PRotate(p, o, alph) {
    return o.add(VRotate(PtoV(o, p), alph));
}

function ShadowPOnLine(p, a, b) {
    const ab = PtoV(a, b);
    const ap = PtoV(a, p);
    const abMod = VecMod(ab);
    if (abMod < EPS) return new Point(a.x, a.y);
    const alph = VecUnit(ab).mul(dMult(ab, ap) / abMod);
    return a.add(alph);
}

function LineCrossCircle(a, b, o, r) {
    const ret = [];
    const t = ShadowPOnLine(o, a, b);
    const ot = PtoV(o, t);
    const otMod = VecMod(ot);
    if (otMod - r > EPS) return ret;
    if (Math.abs(otMod - r) < EPS) {
        ret.push(t);
        return ret;
    }
    const lr = Math.sqrt(r * r - VecMod2(ot));
    const taDir = VecUnit(PtoV(t, a));
    const tbDir = VecUnit(PtoV(t, b));
    ret.push(t.add(taDir.mul(lr)));
    ret.push(t.add(tbDir.mul(lr)));
    return ret;
}

function PointTangentCircle(p, o, r) {
