    // But formula uses p-o. Let's check C++ implementation:
    // double x2 = VecMod2(p-o);
    // Point q1 = o + (p-o) * (r*r/x2);
    // Point q2 = (p-o).rot90() * (-r*sqrt(d2) / x2);
