const EPS = 1e-6;
const PI = Math.acos(-1.0);

class Point {
    constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
    }

    static from(obj) {
        return new Point(obj.x, obj.y);
    }

    set(x, y) {
        this.x = x;
        this.y = y;
        return this;
    }

    clone() {
        return new Point(this.x, this.y);
    }

    add(other) {
        return new Point(this.x + other.x, this.y + other.y);
    }

    sub(other) {
        return new Point(this.x - other.x, this.y - other.y);
    }

    mul(k) {
        return new Point(this.x * k, this.y * k);
    }

    div(k) {
        return this.mul(1.0 / k);
    }

    rot90() {
        return new Point(-this.y, this.x);
    }

    // Length (modulus)
    mod() {
        return Math.hypot(this.x, this.y);
    }

    mod2() {
        return this.x * this.x + this.y * this.y;
    }

    // Unit vector
    unit() {
        const m = this.mod();
        return m < EPS ? new Point(0, 0) : this.div(m);
    }
}

// Vector operations as standalone functions for clarity matching C++ style
function dot(a, b) {
    return a.x * b.x + a.y * b.y;
}

function cross(a, b) {
    return a.x * b.y - a.y * b.x;
}

function length(v) {
    return Math.hypot(v.x, v.y);
}

function length2(v) {
    return v.x * v.x + v.y * v.y;
}

function angleBetween(v1, v2) {
    // Returns angle in radians [0, PI]
    const cosVal = dot(v1, v2) / (length(v1) * length(v2));
    // Clamp for safety
    const clamped = Math.max(-1, Math.min(1, cosVal));
    return Math.acos(clamped);
}

function rotate(v, alpha) {
    const sa = Math.sin(alpha);
    const ca = Math.cos(alpha);
    return new Point(v.x * ca - v.y * sa, v.x * sa + v.y * ca);
}

function projectOnLine(p, a, b) {
    // Foot of perpendicular from p to line ab
    const ab = b.sub(a);
    const ap = p.sub(a);
    const abUnit = ab.unit();
    const projLen = dot(ab, ap) / length(ab);
    return a.add(abUnit.mul(projLen));
}

function lineCircleIntersection(a, b, o, r) {
    // Line AB intersection with Circle O, r
    const ret = [];
    const t = projectOnLine(o, a, b);
    const ot = t.sub(o);
    const d = length(ot);

    if (d - r > EPS) return ret; // No intersection

    if (Math.abs(d - r) < EPS) { // Tangent
        ret.push(t);
        return ret;
    }

    const lr = Math.sqrt(Math.max(0, r * r - d * d));
    const dir = a.sub(t).unit(); // Direction along line
    // Note: C++ uses VecUnit(PtoV(t,a)) and VecUnit(PtoV(t,b)) which are opposite directions.
    // We need both points: t + dir * lr and t - dir * lr
    ret.push(t.add(dir.mul(lr)));
    ret.push(t.sub(dir.mul(lr)));
    return ret;
}

function pointTangentCircle(p, o, r) {
    // Tangent points from p to circle (o, r)
    const ret = [];
    const op = p.sub(o);
    const x2 = length2(op);
    const d2 = x2 - r * r;

    if (d2 < -EPS) return ret; // Inside circle
    if (r <= EPS) { // Circle is a point
        ret.push(o.clone());
        ret.push(o.clone());
        return ret;
    }

    const d2Safe = Math.max(0, d2);
    // q1 = o + (p-o) * (r^2 / |p-o|^2)
    const q1 = o.add(op.mul(r * r / x2));
    // q2 = (p-o).rot90() * (-r * sqrt(d2) / x2)
    const q2 = op.rot90().mul(-r * Math.sqrt(d2Safe) / x2);

    ret.push(q1.sub(q2));
    ret.push(q1.add(q2));
    return ret;
}

function onSegment(p, a, b) {
    // Check if p is on segment ab
    if (Math.abs(cross(b.sub(a), p.sub(a))) > EPS) return false;
    if (Math.min(a.x, b.x) - EPS > p.x || p.x > Math.max(a.x, b.x) + EPS) return false;
    if (Math.min(a.y, b.y) - EPS > p.y || p.y > Math.max(a.y, b.y) + EPS) return false;
    return true;
}

function distanceToLine(p, a, b) {
    return length(projectOnLine(p, a, b).sub(p));
}

// Global variables for check function
let p, s, vp, vs, r, sita;

function check(t) {
    const len_or = p.mod();
    // Planet position at time t
    const angle = sita + t * vp / len_or;
    const e = new Point(len_or * Math.cos(angle), len_or * Math.sin(angle));

    // Check intersection of segment s-e with circle (0,0) radius r
    const ccp = lineCircleIntersection(s, e, new Point(0, 0), r);

    // If no intersection (size != 2) or intersection points not on segment
    // Note: lineCircleIntersection returns intersections with infinite line.
    // We need to check if they lie on segment s-e.
    let hasIntersectionOnSegment = false;
    if (ccp.length === 2) {
        if (onSegment(ccp[0], s, e) || onSegment(ccp[1], s, e)) {
            hasIntersectionOnSegment = true;
        }
    }

    if (!hasIntersectionOnSegment) {
        // Straight line path
        return vs * t > e.sub(s).mod();
    }

    // Path goes around circle: Tangent from s -> Arc -> Tangent to e
    let ttp1 = pointTangentCircle(s, new Point(0, 0), r);
    // Select tangent point closer to the line s-e (or rather, the correct side)
    // C++ sorts by distance to line s-e. 
    // Actually it swaps if dist(ttp1[0]) > dist(ttp1[1]), so ttp1[0] becomes the closer one.
    // Wait, C++: if( PDisLine(ttp1[0],s,e) > PDisLine(ttp1[1],s,e) ) swap.
    // So ttp1[0] is the tangent point with SMALLER distance to line s-e.
    if (distanceToLine(ttp1[0], s, e) > distanceToLine(ttp1[1], s, e)) {
        [ttp1[0], ttp1[1]] = [ttp1[1], ttp1[0]];
    }
    const l1 = s.sub(ttp1[0]).mod();

    let ttp2 = pointTangentCircle(e, new Point(0, 0), r);
    if (distanceToLine(ttp2[0], s, e) > distanceToLine(ttp2[1], s, e)) {
        [ttp2[0], ttp2[1]] = [ttp2[1], ttp2[0]];
    }
    const l2 = e.sub(ttp2[0]).mod();

    // Angle between vectors O->ttp1[0] and O->ttp2[0]
    const v1 = ttp1[0]; // since O is (0,0)
    const v2 = ttp2[0];
    const alph = angleBetween(v1, v2);

    const pathLen = l1 + l2 + alph * r;
    return pathLen < vs * t;
}

function solve() {
    const input = require('fs').readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0) return;
    let idx = 0;
    const out = [];
    while (idx < input.length) {
        const px = parseFloat(input[idx++]);
        const py = parseFloat(input[idx++]);
        vp = parseFloat(input[idx++]);
        const sx = parseFloat(input[idx++]);
        const sy = parseFloat(input[idx++]);
        vs = parseFloat(input[idx++]);
        r = parseFloat(input[idx++]);

        p = new Point(px, py);
        s = new Point(sx, sy);

        sita = Math.acos(Math.max(-1, Math.min(1, p.x / p.mod())));
        if (p.y < 0) sita = -sita;

        let left = 0;
        let right = 1e10;
        // Binary search for 1e-12 precision
        for (let iter = 0; iter < 100; iter++) { // 100 iterations enough for 1e-30
            const mid = (left + right) * 0.5;
            if (check(mid)) {
                right = mid;
            } else {
                left = mid;
            }
        }
        out.push(left.toFixed(9));
    }
    console.log(out.join('\n'));
}

solve();

